1	/**
2	 * Unified video provider dispatcher.
3	 * Resolves the correct embed URL based on the video's provider field.
4	 */
5	
6	import { getVdoCipherOtp } from "./vdocipher";
7	import { getBunnyEmbedUrl } from "./bunny";
8	import { getYouTubeEmbedUrl } from "./youtube";
9	
10	export type VideoProvider = "vdocipher" | "bunny" | "youtube";
11	
12	export interface VideoEmbedResult {
13	  embedUrl: string;
14	  provider: VideoProvider;
15	  signed: boolean;
16	  expiresInSeconds: number | null;
17	}
18	
19	/**
20	 * Given a video record's provider + providerVideoId (with legacy vdoCipherId fallback),
21	 * returns a ready-to-embed URL for the player iframe.
22	 */
23	export async function resolveEmbedUrl(video: {
24	  videoProvider: string;
25	  providerVideoId: string;
26	  vdoCipherId: string;
27	}): Promise<VideoEmbedResult> {
28	  const provider = (video.videoProvider || "vdocipher") as VideoProvider;
29	
30	  // Legacy rows have providerVideoId="" and vdoCipherId set — fall back gracefully.
31	  const id = video.providerVideoId || video.vdoCipherId;
32	
33	  if (!id) {
34	    throw new Error("Video has no provider ID configured");
35	  }
36	
37	  switch (provider) {
38	    case "bunny": {
39	      const result = await getBunnyEmbedUrl(id);
40	      return { embedUrl: result.embedUrl, provider, signed: result.signed, expiresInSeconds: result.expiresInSeconds };
41	    }
42	    case "youtube": {
43	      const result = getYouTubeEmbedUrl(id);
44	      return { embedUrl: result.embedUrl, provider, signed: false, expiresInSeconds: null };
45	    }
46	    case "vdocipher":
47	    default: {
48	      const result = await getVdoCipherOtp(id);
49	      return { embedUrl: result.embedUrl, provider: "vdocipher", signed: true, expiresInSeconds: 3600 };
50	    }
51	  }
52	}
53	
54	export const PROVIDER_LABELS: Record<VideoProvider, string> = {
55	  vdocipher: "VdoCipher",
56	  bunny: "Bunny Stream",
57	  youtube: "YouTube Private",
58	};
59	
60	/** Validates a provider ID format per provider rules */
61	export function validateProviderId(provider: VideoProvider, id: string): string | null {
62	  if (!id || !id.trim()) return "معرف الفيديو مطلوب";
63	
64	  switch (provider) {
65	    case "vdocipher":
66	      if (!/^[a-z0-9-]+$/i.test(id)) return "معرف VdoCipher يحتوي على أحرف وأرقام وشرطات فقط";
67	      break;
68	    case "bunny":
69	      if (!/^[a-z0-9-]+$/i.test(id)) return "معرف Bunny Stream يحتوي على أحرف وأرقام وشرطات فقط";
70	      break;
71	    case "youtube":
72	      // YouTube video IDs are exactly 11 chars: letters, digits, -, _
73	      if (!/^[a-zA-Z0-9_-]{11}$/.test(id)) return "معرف YouTube يجب أن يكون 11 حرفاً (مثال: dQw4w9WgXcQ)";
74	      break;
75	  }
76	  return null;
77	}

1	/**
2	 * Bunny Stream integration for secure video playback.
3	 * Bunny signed URLs require a token derived from: SHA256(securityKey + videoPath + expiry + ip)
4	 * We use the embed player URL with a signed token so students can't extract the CDN URL.
5	 */
6	
7	const BUNNY_API_KEY = process.env.BUNNY_API_KEY ?? "";
8	const BUNNY_LIBRARY_ID = process.env.BUNNY_LIBRARY_ID ?? "";
9	const BUNNY_TOKEN_KEY = process.env.BUNNY_TOKEN_AUTHENTICATION_KEY ?? "";
10	// Base pull zone hostname — e.g. "iframe.mediadelivery.net"
11	const BUNNY_CDN_HOSTNAME = process.env.BUNNY_CDN_HOSTNAME ?? "iframe.mediadelivery.net";
12	
13	export interface BunnyEmbedResponse {
14	  embedUrl: string;
15	  signed: boolean;
16	  expiresInSeconds: number;
17	}
18	
19	function hexSha256(data: Uint8Array<ArrayBuffer>): Promise<string> {
20	  return crypto.subtle.digest("SHA-256", data).then((buf) =>
21	    Array.from(new Uint8Array(buf))
22	      .map((b) => b.toString(16).padStart(2, "0"))
23	      .join("")
24	  );
25	}
26	
27	export async function getBunnyEmbedUrl(videoId: string): Promise<BunnyEmbedResponse> {
28	  const TTL_SECONDS = 3600;
29	
30	  if (!BUNNY_TOKEN_KEY || !BUNNY_LIBRARY_ID) {
31	    if (!BUNNY_API_KEY && !BUNNY_LIBRARY_ID) {
32	      // Full mock: no env vars at all
33	      return {
34	        embedUrl: `https://${BUNNY_CDN_HOSTNAME}/embed/${BUNNY_LIBRARY_ID || "0"}/${videoId}`,
35	        signed: false,
36	        expiresInSeconds: TTL_SECONDS,
37	      };
38	    }
39	    // Library ID set but no token key — return unsigned embed URL
40	    return {
41	      embedUrl: `https://${BUNNY_CDN_HOSTNAME}/embed/${BUNNY_LIBRARY_ID}/${videoId}`,
42	      signed: false,
43	      expiresInSeconds: TTL_SECONDS,
44	    };
45	  }
46	
47	  // Bunny signed embed URL token formula:
48	  // token = SHA256(tokenKey + videoId + expiry)
49	  // URL: https://iframe.mediadelivery.net/embed/{libraryId}/{videoId}?token={token}&expires={expiry}
50	  const expiry = Math.floor(Date.now() / 1000) + TTL_SECONDS;
51	  const raw = `${BUNNY_TOKEN_KEY}${videoId}${expiry}`;
52	  const token = await hexSha256(new TextEncoder().encode(raw) as unknown as Uint8Array<ArrayBuffer>);
53	
54	  const embedUrl =
55	    `https://${BUNNY_CDN_HOSTNAME}/embed/${BUNNY_LIBRARY_ID}/${videoId}` +
56	    `?token=${token}&expires=${expiry}&autoplay=false`;
57	
58	  return { embedUrl, signed: true, expiresInSeconds: TTL_SECONDS };
59	}

1	import { NextRequest, NextResponse } from "next/server";
