9	// Verify an existing watch session (used when loading the watch page on refresh)
10	export async function GET(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
11	  const session = await getStudentSession();
12	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
13	
14	  const { id: videoId } = await params;
15	  const { searchParams } = new URL(req.url);
16	  const sessionToken = searchParams.get("token");
17	
18	  if (!sessionToken) {
19	    return NextResponse.json({ error: "token مطلوب" }, { status: 400 });
20	  }
21	
22	  const watchSession = await prisma.videoWatchSession.findUnique({
23	    where: { sessionToken },
24	    include: {
25	      video: {
26	        include: {
27	          folder: {
28	            select: {
29	              publishAt: true,
30	              course: { select: { id: true, title: true, teacherId: true } },
31	            },
32	          },
33	        },
34	      },
35	    },
36	  });
37	
38	  if (!watchSession) {
39	    return NextResponse.json({ error: "الجلسة غير موجودة" }, { status: 404 });
40	  }
41	  if (watchSession.studentId !== session.id) {
42	    return NextResponse.json({ error: "غير مصرح بهذه الجلسة" }, { status: 403 });
43	  }
44	  if (watchSession.videoId !== videoId) {
45	    return NextResponse.json({ error: "الفيديو لا يتطابق مع الجلسة" }, { status: 400 });
46	  }
47	
48	  const now = new Date();
49	  const isExpired = watchSession.expiresAt < now || !!watchSession.endedAt;
50	
51	  // Per-video watch quota
52	  const usedWatchCount = await prisma.videoWatchSession.count({
53	    where: { studentId: session.id, videoId, usedWatchSlot: true },
54	  });
55	
56	  const video = watchSession.video;
57	  const course = video.folder.course;
58	  const total = video.maxWatchesPerUser;
59	
60	  const profile = await prisma.teacherProfile.findUnique({
61	    where: { teacherId: course.teacherId },
62	    select: { slug: true },
63	  });
64	  const teacherSlug = profile?.slug ?? "";
65	
66	  let studentPlan = "course";
67	  const planEnrollmentForVideo = await prisma.planEnrollment.findFirst({
68	    where: {
69	      studentId: session.id,
70	      expiresAt: { gt: now },
71	      plan: {
72	        lessons: {
73	          some: {
74	            sources: {
75	              some: {
76	                videoId
77	              }
78	            }
79	          }
80	        }
81	      }
82	    },
83	    select: { id: true }
84	  });
85	
86	  if (planEnrollmentForVideo) {
87	    studentPlan = "plan";
88	  } else {
89	    const hasVideoAccess = await prisma.accessCode.findFirst({
90	      where: { studentId: session.id, videoId, isActive: true, accessType: "VIDEO" },
91	    }) || await prisma.videoPurchase.findUnique({
92	      where: { studentId_videoId: { studentId: session.id, videoId } },
93	    });
94	
95	    if (hasVideoAccess) {
96	      studentPlan = "lesson";
97	    } else {
98	      const folderId = video.folderId;
99	      const hasFolderAccess = await prisma.accessCode.findFirst({
100	        where: { studentId: session.id, folderId, isActive: true, accessType: "FOLDER" },
101	      }) || await prisma.folderPurchase.findUnique({
102	        where: { studentId_folderId: { studentId: session.id, folderId } },
103	      });
104	
105	      if (hasFolderAccess) {
106	        studentPlan = "folder";
107	      }
108	    }
109	  }
110	
111	  return NextResponse.json({
112	    videoId,
113	    sessionToken,
114	    sessionId: watchSession.id,
115	    isExpired,
116	    startedAt: watchSession.startedAt.toISOString(),
117	    expiresAt: watchSession.expiresAt.toISOString(),
118	    remainingWatches: Math.max(0, total - usedWatchCount),
119	    totalWatches: total,
120	    usedWatches: usedWatchCount,
121	    teacherSlug,
122	    studentPlan,
123	    video: {
124	      id: video.id,
125	      title: video.title,
126	      vdoCipherId: video.vdoCipherId,
127	      videoProvider: video.videoProvider,
128	      providerVideoId: video.providerVideoId,
129	      courseId: course.id,
130	      courseTitle: course.title,
131	    },
132	  });
133	}
