135	export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
136	  // Session may be null for anonymous viewers of a free/demo video. Use the
137	  // role-agnostic session so admins/superadmins can preview too.
138	  const session = await getSession();
139	
140	  // Watch-session length is superadmin-configurable (was 4h); ≥0.25h so a bad
141	  // value can't create instantly-expired sessions.
142	  const WATCH_DURATION_HOURS = await getConfigNumberClamped("watch_session_hours", 0.25, 720);
143	
144	  const { id: videoId } = await params;
145	  const ipAddress = req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ?? null;
146	
147	  const video = await prisma.video.findUnique({
148	    where: { id: videoId },
149	    include: {
150	      folder: {
151	        select: {
152	          courseId: true,
153	          publishAt: true,
154	          course: { select: { id: true, title: true, teacherId: true } },
155	        },
156	      },
157	    },
158	  });
159	
160	  if (!video) {
161	    return NextResponse.json({ error: "الفيديو غير موجود" }, { status: 404 });
162	  }
163	
164	  const course = video.folder.course;
165	  const now = new Date();
166	
167	  // ── Scheduled unlock: a not-yet-published video can't start a session ──────
168	  if (isScheduledLocked(video.folder.publishAt, video.publishAt, now.getTime())) {
169	    return NextResponse.json(
170	      {
171	        error: "هذه المحاضرة لم تُفتح بعد. ستتاح في موعدها المحدد.",
172	        code: "SCHEDULED",
173	        unlockAt: unlockAtISO(video.folder.publishAt, video.publishAt),
174	      },
175	      { status: 403 }
176	    );
177	  }
178	
179	  // ── FREE / DEMO video: bypass enrollment + quota, no session row consumed ──
180	  if (video.isFree) {
181	    const embedResult = await resolveEmbedUrl(video);
182	    const expiresAt = new Date(now.getTime() + WATCH_DURATION_HOURS * 60 * 60 * 1000);
183	    return NextResponse.json({
184	      sessionToken: "free",
185	      expiresAt: expiresAt.toISOString(),
186	      watchDurationHours: WATCH_DURATION_HOURS,
187	      remainingWatches: null,
188	      totalWatches: null,
189	      usedWatches: 0,
190	      embedUrl: embedResult.embedUrl,
191	      provider: embedResult.provider,
192	      free: true,
193	    });
194	  }
195	
196	  // ── PAID video from here on — requires a logged-in student ──
197	  if (!session) {
198	    return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
199	  }
200	
201	  // Teacher/staff have no place in the student watch flow.
202	  if (session.role === "teacher" || session.role === "staff") {
203	    return NextResponse.json(
204	      { error: "صفحة مشاهدة الكورس مخصّصة للطلاب فقط.", code: "ROLE_NOT_ALLOWED" },
205	      { status: 403 }
206	    );
207	  }
208	
209	  // Admin / superadmin: preview playback — no enrollment, no quota, no slot used.
210	  if (session.role === "admin" || session.role === "superadmin") {
211	    const embedResult = await resolveEmbedUrl(video);
212	    const expiresAt = new Date(now.getTime() + WATCH_DURATION_HOURS * 60 * 60 * 1000);
213	    return NextResponse.json({
214	      sessionToken: "preview",
215	      expiresAt: expiresAt.toISOString(),
216	      watchDurationHours: WATCH_DURATION_HOURS,
217	      remainingWatches: null,
218	      totalWatches: null,
219	      usedWatches: 0,
220	      embedUrl: embedResult.embedUrl,
221	      provider: embedResult.provider,
222	      preview: true,
223	    });
224	  }
225	
226	  // Device lock: a device-bound token whose device was reset/removed can't play.
227	  // (Legacy tokens issued before the feature have no deviceId — allowed.)
228	  if (session.deviceId) {
229	    const device = await prisma.device.findUnique({
230	      where: { userId_deviceId: { userId: session.id, deviceId: session.deviceId } },
231	    });
232	    if (!device) {
233	      return NextResponse.json(
234	        { error: "تم إلغاء تفعيل هذا الجهاز. يرجى تسجيل الدخول من جديد.", code: "DEVICE_REVOKED" },
235	        { status: 403 }
236	      );
237	    }
238	  }
239	
240	  // Verify access via centralized checkVideoAccess
241	  const hasAccess = await checkVideoAccess(session.id, session.role, videoId);
242	  if (!hasAccess) {
243	    return NextResponse.json({ error: "لا يوجد صلاحية للوصول لهذا الكورس" }, { status: 403 });
244	  }
245	
246	  // Reuse an existing active session for this student + video
247	  const activeSession = await prisma.videoWatchSession.findFirst({
248	    where: { studentId: session.id, videoId, endedAt: null, expiresAt: { gt: now } },
249	    orderBy: { startedAt: "desc" },
250	  });
251	
252	  if (activeSession) {
253	    const activeUsedWatchCount = await prisma.videoWatchSession.count({
254	      where: { studentId: session.id, videoId, usedWatchSlot: true },
255	    });
256	
257	    const embedResult = await resolveEmbedUrl(video);
258	
259	    const profile = await prisma.teacherProfile.findUnique({
260	      where: { teacherId: course.teacherId },
261	      select: { slug: true },
262	    });
263	    const teacherSlug = profile?.slug ?? "";
264	
265	    let studentPlan = "course";
266	    const isPlanStudent = await prisma.planEnrollment.findFirst({
267	      where: {
268	        studentId: session.id,
269	        expiresAt: { gt: now },
270	        plan: {
271	          lessons: {
272	            some: {
273	              sources: {
274	                some: {
275	                  videoId
276	                }
277	              }
278	            }
279	          }
280	        }
281	      },
282	      select: { id: true }
283	    });
284	
285	    if (isPlanStudent) {
286	      studentPlan = "plan";
287	    } else {
288	      const hasVideoAccess = await prisma.accessCode.findFirst({
289	        where: { studentId: session.id, videoId, isActive: true, accessType: "VIDEO" },
290	      }) || await prisma.videoPurchase.findUnique({
291	        where: { studentId_videoId: { studentId: session.id, videoId } },
292	      });
293	
294	      if (hasVideoAccess) {
295	        studentPlan = "lesson";
296	      } else {
297	        const folderId = video.folderId;
298	        const hasFolderAccess = await prisma.accessCode.findFirst({
299	          where: { studentId: session.id, folderId, isActive: true, accessType: "FOLDER" },
300	        }) || await prisma.folderPurchase.findUnique({
301	          where: { studentId_folderId: { studentId: session.id, folderId } },
302	        });
303	
304	        if (hasFolderAccess) {
305	          studentPlan = "folder";
306	        }
307	      }
308	    }
309	
310	    return NextResponse.json({
311	      sessionToken: activeSession.sessionToken,
312	      sessionId: activeSession.id,
313	      expiresAt: activeSession.expiresAt.toISOString(),
314	      watchDurationHours: WATCH_DURATION_HOURS,
315	      remainingWatches: Math.max(0, video.maxWatchesPerUser - activeUsedWatchCount),
316	      totalWatches: video.maxWatchesPerUser,
317	      usedWatches: activeUsedWatchCount,
318	      embedUrl: embedResult.embedUrl,
319	      provider: embedResult.provider,
320	      reused: true,
321	      teacherSlug,
322	      studentPlan,
323	    });
324	  }
325	  
326	  const planEnrollment = await prisma.planEnrollment.findFirst({
327	    where: {
328	      studentId: session.id,
329	      expiresAt: { gt: now },
330	      plan: {
331	        lessons: {
332	          some: {
333	            sources: {
334	              some: {
335	                videoId: video.id
336	              }
337	            }
338	          }
339	        }
340	      }
341	    },
342	    select: { id: true }
343	  });
344	  const hasPlanAccess = !!planEnrollment;
345	
346	  const sessionToken = crypto.randomUUID();
347	  const expiresAt = new Date(now.getTime() + WATCH_DURATION_HOURS * 60 * 60 * 1000);
348	  const userAgent = req.headers.get("user-agent") ?? null;
349	
350	  // ── Atomic quota check + slot consumption ──────────────────────────────────
351	  // The per-video watch limit is the guardrail protecting paid content. Reading
352	  // the count and creating the session in separate statements lets two tabs both
353	  // grab the last slot. Doing it in one transaction closes that: Serializable
354	  // isolation (Postgres/prod) aborts the conflicting tx; SQLite (local) serializes
355	  // writers, so the race can't occur there either.
356	  const QUOTA_EXCEEDED = "QUOTA_EXCEEDED";
357	  const isPg = (process.env.DATABASE_URL ?? "").startsWith("postgres");
358	  try {
359	    const { used, ws } = await prisma.$transaction(
360	      async (tx) => {
361	        const usedCount = await tx.videoWatchSession.count({
362	          where: { studentId: session.id, videoId, usedWatchSlot: true },
363	        });
364	        if (usedCount >= video.maxWatchesPerUser) throw new Error(QUOTA_EXCEEDED);
365	        await tx.videoWatchSession.updateMany({
366	          where: { studentId: session.id, videoId, endedAt: null, expiresAt: { lt: now } },
367	          data: { endedAt: now },
368	        });
369	        const created = await tx.videoWatchSession.create({
370	          data: { sessionToken, videoId, studentId: session.id, expiresAt, usedWatchSlot: true, ipAddress, userAgent },
371	        });
372	        return { used: usedCount, ws: created };
373	      },
374	      isPg ? { isolationLevel: "Serializable" } : undefined
375	    );
376	
377	    const profile = await prisma.teacherProfile.findUnique({
378	      where: { teacherId: course.teacherId },
379	      select: { slug: true },
380	    });
381	    const teacherSlug = profile?.slug ?? "";
382	
383	    let studentPlan = "course";
384	    if (hasPlanAccess) {
385	      studentPlan = "plan";
386	    } else {
387	      const hasVideoAccess = await prisma.accessCode.findFirst({
388	        where: { studentId: session.id, videoId, isActive: true, accessType: "VIDEO" },
389	      }) || await prisma.videoPurchase.findUnique({
390	        where: { studentId_videoId: { studentId: session.id, videoId } },
391	      });
392	
393	      if (hasVideoAccess) {
394	        studentPlan = "lesson";
395	      } else {
396	        const folderId = video.folderId;
397	        const hasFolderAccess = await prisma.accessCode.findFirst({
398	          where: { studentId: session.id, folderId, isActive: true, accessType: "FOLDER" },
399	        }) || await prisma.folderPurchase.findUnique({
400	          where: { studentId_folderId: { studentId: session.id, folderId } },
401	        });
402	
403	        if (hasFolderAccess) {
404	          studentPlan = "folder";
405	        }
406	      }
407	    }
408	
409	    const embedResult = await resolveEmbedUrl(video);
410	    return NextResponse.json({
411	      sessionToken,
412	      sessionId: ws.id,
413	      expiresAt: expiresAt.toISOString(),
414	      watchDurationHours: WATCH_DURATION_HOURS,
415	      remainingWatches: video.maxWatchesPerUser - used - 1,
416	      totalWatches: video.maxWatchesPerUser,
417	      usedWatches: used + 1,
418	      embedUrl: embedResult.embedUrl,
419	      provider: embedResult.provider,
420	      teacherSlug,
421	      studentPlan,
422	    });
423	  } catch (e) {
424	    if (e instanceof Error && e.message === QUOTA_EXCEEDED) {
425	      return NextResponse.json(
426	        {
427	          error: `لقد استنفدت جميع محاولات المشاهدة لهذا الفيديو (${video.maxWatchesPerUser} مشاهدة)`,
428	          code: "NO_WATCHES_REMAINING",
429	        },
430	        { status: 403 }
431	      );
432	    }
433	    // Write conflict (a concurrent tab won the slot) → ask to retry.
434	    if ((e as { code?: string }).code === "P2034") {
435	      return NextResponse.json(
436	        { error: "حدث تزامن في الطلب، حاول مرة أخرى", code: "CONCURRENT_RETRY" },
437	        { status: 409 }
438	      );
439	    }
440	    console.error("Watch-session transaction error:", e);
441	    return NextResponse.json({ error: "تعذر بدء جلسة المشاهدة" }, { status: 500 });
442	  }
443	}

