1	import { NextRequest, NextResponse } from "next/server";
2	import { getStudentSession } from "@/lib/auth";
3	import { prisma } from "@/lib/prisma";
4	import { checkVideoAccess } from "@/lib/authorization";
5	
6	/**
7	 * Resume-playback position for a (student, video) pair. Stored on Progress so it
8	 * survives the 4-hour watch-session boundary — see the schema note on Progress.
9	 *
10	 * GET  → { seconds, watched } the last saved position (0 if none).
11	 * POST → { seconds, deltaWatchedSeconds? } upserts the position and increments
12	 *        cumulative watchedSecondsTotal (server-side addition only, with an
13	 *        anti-cheat clamp against clock tampering).
14	 */
15	
16	const MAX_POSITION = 24 * 60 * 60; // 24h cap — guards against bogus values
17	
18	// In-memory rate-limit map: studentId:videoId → last ping timestamp.
19	// Cleared automatically when the server restarts; intentionally transient.
20	const lastPingMap = new Map<string, number>();
21	
22	export async function GET(_req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
23	  const session = await getStudentSession();
24	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
25	
26	  const { id: videoId } = await params;
27	  const hasAccess = await checkVideoAccess(session.id, session.role, videoId);
28	  if (!hasAccess) {
29	    return NextResponse.json({ error: "غير مصرح لك بالوصول لهذا الفيديو" }, { status: 403 });
30	  }
31	
32	  const progress = await prisma.progress.findUnique({
33	    where: { studentId_videoId: { studentId: session.id, videoId } },
34	    select: { lastPositionSeconds: true, watched: true },
35	  });
36	
37	  return NextResponse.json({
38	    seconds: progress?.lastPositionSeconds ?? 0,
39	    watched: progress?.watched ?? false,
40	  });
41	}
42	
43	export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
44	  const session = await getStudentSession();
45	  if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
46	
47	  const { id: videoId } = await params;
48	  const hasAccess = await checkVideoAccess(session.id, session.role, videoId);
49	  if (!hasAccess) {
50	    return NextResponse.json({ error: "غير مصرح لك بالوصول لهذا الفيديو" }, { status: 403 });
51	  }
52	
53	  const body = (await req.json().catch(() => ({}))) as {
54	    seconds?: number;
55	    deltaWatchedSeconds?: number;
56	  };
57	
58	  const raw = Number(body.seconds);
59	  if (!Number.isFinite(raw) || raw < 0) {
60	    return NextResponse.json({ error: "قيمة غير صالحة" }, { status: 400 });
61	  }
62	  const seconds = Math.min(Math.round(raw), MAX_POSITION);
63	
64	  // Only persist for a video that actually exists (avoids orphan rows).
65	  const exists = await prisma.video.findUnique({ where: { id: videoId }, select: { id: true } });
66	  if (!exists) return NextResponse.json({ error: "الفيديو غير موجود" }, { status: 404 });
67	
68	  // ── Anti-cheat clamp for deltaWatchedSeconds ─────────────────────────────
69	  // The client sends how many seconds of video it claims to have played since
70	  // its last ping. We clamp this to wall-clock time × 1.1 (10% tolerance for
71	  // minor timing jitter). If no previous ping exists, we accept the delta as-is
72	  // up to a hard max of 10s (the server-side interval).
73	  let safeDelta = 0;
74	  const rawDelta = Number(body.deltaWatchedSeconds);
75	  if (Number.isFinite(rawDelta) && rawDelta > 0) {
76	    const key = `${session.id}:${videoId}`;
77	    const now = Date.now();
78	    const lastPing = lastPingMap.get(key) ?? 0;
79	
80	    if (lastPing > 0) {
81	      const wallClockSeconds = (now - lastPing) / 1000;
82	      safeDelta = Math.min(rawDelta, wallClockSeconds * 1.1);
83	    } else {
84	      // First ping of this session — accept up to 10s (one interval)
85	      safeDelta = Math.min(rawDelta, 10);
86	    }
87	    safeDelta = Math.max(0, safeDelta);
88	    lastPingMap.set(key, now);
89	
90	    // Prune stale entries every ~1000 writes to avoid unbounded growth
91	    if (lastPingMap.size > 10000) {
92	      const cutoff = now - 3600_000; // 1h stale
93	      for (const [k, v] of lastPingMap) {
94	        if (v < cutoff) lastPingMap.delete(k);
95	      }
96	    }
97	  }
98	
99	  // ── Upsert ───────────────────────────────────────────────────────────────
100	  await prisma.progress.upsert({
101	    where: { studentId_videoId: { studentId: session.id, videoId } },
102	    update: {
103	      lastPositionSeconds: seconds,
104	      positionUpdatedAt: new Date(),
105	      lastWatchedAt: new Date(),
106	      ...(safeDelta > 0 ? { watchedSecondsTotal: { increment: safeDelta } } : {}),
107	    },
108	    create: {
109	      studentId: session.id,
110	      videoId,
111	      lastPositionSeconds: seconds,
112	      positionUpdatedAt: new Date(),
113	      lastWatchedAt: new Date(),
114	      watchedSecondsTotal: safeDelta,
115	    },
116	  });
117	
118	  return NextResponse.json({ ok: true, seconds });
119	}

