32	
33	    const { id: folderId } = await params;
34	    const body = (await req.json()) as {
35	      title?: string;
36	      videoProvider?: string;
37	      providerVideoId?: string;
38	      durationMinutes?: number;
39	      maxWatchesPerUser?: number;
40	      publishAt?: string | null;
41	      // Legacy field — accepted for backwards compat, treated as vdocipher
42	      vdoCipherId?: string;
43	    };
44	
45	    const durationMinutes =
46	      typeof body.durationMinutes === "number" && body.durationMinutes >= 0
47	        ? Math.floor(body.durationMinutes)
48	        : 0;
49	
50	    // Default watch quota for new videos is superadmin-configurable (was 3).
51	    const maxWatchesPerUser =
52	      typeof body.maxWatchesPerUser === "number" && body.maxWatchesPerUser >= 1
53	        ? Math.floor(body.maxWatchesPerUser)
54	        : await getConfigNumberClamped("default_max_watches", 1, 99);
55	
56	    const { title } = body;
57	
58	    // Resolve provider + id (support legacy vdoCipherId field)
59	    const videoProvider: VideoProvider = VALID_PROVIDERS.includes(body.videoProvider as VideoProvider)
60	      ? (body.videoProvider as VideoProvider)
61	      : "vdocipher";
62	
63	    const providerVideoId = (body.providerVideoId ?? body.vdoCipherId ?? "").trim();
64	
65	    if (!title || typeof title !== "string" || !title.trim()) {
66	      return NextResponse.json({ error: "عنوان الفيديو مطلوب" }, { status: 400 });
67	    }
68	    if (title.length > MAX_TITLE_LENGTH) {
69	      return NextResponse.json(
70	        { error: `عنوان الفيديو لا يمكن أن يزيد عن ${MAX_TITLE_LENGTH} حرف` },
71	        { status: 400 }
72	      );
73	    }
74	
75	    const idError = validateProviderId(videoProvider, providerVideoId);
76	    if (idError) {
77	      return NextResponse.json({ error: idError }, { status: 400 });
78	    }
