1	import crypto from "crypto";
2	import { prisma } from "@/lib/prisma";
3	
4	export class AccessCodeGuard {
5	  private static SERVER_SECRET = process.env.ACCESS_CODE_SECRET || "codeup_access_code_server_secret_2026";
6	
7	  /**
8	   * Generates a cryptographically secure, high-entropy access code.
9	   * Example output: "P9X7-WK4M-QT2H"
10	   */
11	  public static generateSecureCode(): string {
12	    const charset = "ABCDEFGHJKLMNPQRSTUVWXYZ23456789";
13	    const getRandomChar = () => charset[crypto.randomInt(0, charset.length)];
14	
15	    const part1 = Array.from({ length: 4 }, getRandomChar).join("");
16	    const part2 = Array.from({ length: 4 }, getRandomChar).join("");
17	    const part3 = Array.from({ length: 4 }, getRandomChar).join("");
18	
19	    return `${part1}-${part2}-${part3}`;
20	  }
21	
22	  /**
23	   * Computes SHA-256 HMAC hash of code using server secret for secure storage at rest.
24	   */
25	  public static hashCode(code: string): string {
26	    const normalized = String(code).trim().toUpperCase();
27	    return crypto
28	      .createHmac("sha256", this.SERVER_SECRET)
29	      .update(normalized)
30	      .digest("hex");
31	  }
32	
33	  /**
34	   * Performs constant-time comparison of two string hashes to prevent timing attacks.
35	   */
36	  public static constantTimeCompare(hashA: string, hashB: string): boolean {
37	    const bufA = Buffer.from(hashA, "utf-8");
38	    const bufB = Buffer.from(hashB, "utf-8");
39	
40	    if (bufA.length !== bufB.length) return false;
41	    return crypto.timingSafeEqual(bufA, bufB);
42	  }
43	
44	  /**
45	   * Exponential rate-limit check per IP and User ID.
46	   * Lockout thresholds:
47	   *   - 5 failures in last 10 mins  => 30-second lock
48	   *   - 10 failures in last 30 mins => 5-minute lock
49	   *   - 20 failures in last 1 hour  => 1-hour lock
50	   */
51	  public static async verifyRateLimit(
52	    ip: string,
53	    userId?: string
54	  ): Promise<{ allowed: boolean; lockTimeSeconds: number; failureCount: number }> {
55	    const oneHourAgo = new Date(Date.now() - 60 * 60 * 1000);
56	
57	    const failures = await prisma.accessCodeLog.count({
58	      where: {
59	        OR: [{ ip }, ...(userId ? [{ userId }] : [])],
60	        success: false,
61	        createdAt: { gte: oneHourAgo },
62	      },
63	    });
64	
65	    if (failures >= 20) {
66	      return { allowed: false, lockTimeSeconds: 3600, failureCount: failures };
67	    }
68	    if (failures >= 10) {
69	      return { allowed: false, lockTimeSeconds: 300, failureCount: failures };
70	    }
71	    if (failures >= 5) {
72	      return { allowed: false, lockTimeSeconds: 30, failureCount: failures };
73	    }
74	
75	    return { allowed: true, lockTimeSeconds: 0, failureCount: failures };
76	  }
77	
78	  /**
79	   * Logs access code redemption attempt for audit telemetry.
80	   * NEVER stores raw code input.
81	   */
82	  public static async logAttempt(params: {
83	    ip: string;
84	    userId?: string;
85	    codeAttempted: string;
86	    success: boolean;
87	  }): Promise<void> {
88	    const rawInput = String(params.codeAttempted || "").trim().toUpperCase();
89	    const attemptHash = this.hashCode(rawInput);
90	    const first4Characters = rawInput.substring(0, 4);
91	    const codeLength = rawInput.length;
92	
93	    await prisma.accessCodeLog.create({
94	      data: {
95	        ip: params.ip,
96	        userId: params.userId,
97	        attemptHash,
98	        first4Characters,
99	        codeLength,
100	        success: params.success,
101	      },
102	    }).catch(() => {});
103	
104	    // Audit Log for security monitoring
105	    await prisma.auditLog.create({
106	      data: {
107	        userId: params.userId,
108	        action: params.success ? "ACCESS_CODE_REDEEMED" : "ACCESS_CODE_FAILED",
109	        ip: params.ip,
110	        metadata: JSON.stringify({
111	          first4: first4Characters,
112	          length: codeLength,
113	          success: params.success,
114	        }),
115	      },
116	    }).catch(() => {});
117	  }
118	}

1	/**
2	 * VdoCipher API integration for secure video playback.
3	 */
4	
5	const VDOCIPHER_API_SECRET = process.env.VDOCIPHER_API_SECRET || "";
6	
7	export interface VdoCipherOtpResponse {
8	  otp: string;
9	  playbackInfo: string;
10	  embedUrl: string;
11	}
12	
13	export async function getVdoCipherOtp(vdoCipherId: string): Promise<VdoCipherOtpResponse> {
14	  // Testable API fallback if no secret is provided or secret is "test"
15	  if (!VDOCIPHER_API_SECRET || VDOCIPHER_API_SECRET === "test") {
16	    console.warn(`[VdoCipher] Using mock OTP for video ${vdoCipherId} because VDOCIPHER_API_SECRET is missing or set to 'test'`);
17	    
18	    // Return dummy tokens. The VdoCipher player will load but show "Invalid OTP" 
19	    // which proves the iframe integration works correctly.
20	    const mockOtp = "mock-otp-12345";
21	    const mockPlaybackInfo = "mock-playback-info-12345";
22	    
23	    return {
24	      otp: mockOtp,
25	      playbackInfo: mockPlaybackInfo,
26	      embedUrl: `https://player.vdocipher.com/v2/?otp=${mockOtp}&playbackInfo=${mockPlaybackInfo}`
27	    };
28	  }
29	
30	  try {
31	    const response = await fetch(`https://dev.vdocipher.com/api/videos/${vdoCipherId}/otp`, {
32	      method: "POST",
33	      headers: {
34	        "Authorization": `Apisecret ${VDOCIPHER_API_SECRET}`,
35	        "Content-Type": "application/json"
36	      },
37	      body: JSON.stringify({
38	        ttl: 3600 // 1 hour token expiration
39	      })
40	    });
41	
42	    if (!response.ok) {
43	      const errorText = await response.text();
44	      console.error(`[VdoCipher API Error] ${response.status}: ${errorText}`);
45	      throw new Error(`VdoCipher API Error: ${response.status}`);
46	    }
47	
48	    const data = await response.json();
49	    return {
50	      otp: data.otp,
51	      playbackInfo: data.playbackInfo,
52	      embedUrl: `https://player.vdocipher.com/v2/?otp=${data.otp}&playbackInfo=${data.playbackInfo}`
53	    };
54	  } catch (error) {
55	    console.error("[VdoCipher] Failed to generate OTP:", error);
56	    throw error;
57	  }
58	}

