151	async function getJwtSession(): Promise<SessionUser | null> {
152	  const cookieStore = await cookies();
153	  const token = cookieStore.get(AUTH_COOKIE_NAME)?.value;
154	  if (!token) {
155	    return null;
156	  }
157	
158	  const payload = await verifyToken(token);
159	  if (!payload) {
160	    return null;
161	  }
162	
163	  if (payload.role === "superadmin") {
164	    // Break-glass: env master-password login carries id "superadmin", no DB row.
165	    if (payload.id === "superadmin") {
166	      return {
167	        id: payload.id,
168	        email: payload.email,
169	        name: payload.name,
170	        role: payload.role,
171	        isOwner: true,
172	        profileCompleted: true,
173	        deviceId: payload.deviceId,
174	      };
175	    }
176	    // Named DB-backed superadmin — re-validate against the row so a
177	    // renamed/suspended/deleted account reflects immediately.
178	    const sa = await prisma.user.findFirst({
179	      where: { id: payload.id, role: "superadmin", isDeleted: false },
180	    });
181	    if (!sa || !sa.isActive) return null;
182	    return {
183	      id: sa.id,
184	      email: sa.email,
185	      name: sa.name,
186	      role: "superadmin",
187	      isOwner: sa.isOwner,
188	      profileCompleted: true,
189	      deviceId: payload.deviceId,
190	    };
191	  }
192	
193	  const user = await prisma.user.findUnique({
194	    where: { id: payload.id },
195	  });
196	
197	  if (!user || !user.isActive || user.isDeleted) {
198	    return null;
199	  }
200	
201	  return {
202	    id: user.id,
203	    email: user.email,
204	    name: user.name,
205	    role: user.role,
206	    profileCompleted: user.profileCompleted,
207	    phone: user.phone,
208	    parentPhone: user.parentPhone,
209	    age: user.age,
210	    educationalStage: user.educationalStage,
211	    createdAt: user.createdAt,
212	    deviceId: payload.deviceId,
213	    referralCode: user.referralCode,
214	    streakFreezes: user.streakFreezes,
215	  };
216	}
