1	/**
2	 * Scheduled-unlock helpers. A video/folder with a null `publishAt` is available
3	 * immediately; a future `publishAt` locks it until then. A video's effective
4	 * unlock time is the LATER of its own and its folder's publishAt — a video can't
5	 * be available before the folder that contains it.
6	 *
7	 * Centralized here so every content read path + the playback gate agree.
8	 */
9	
10	type DateInput = Date | string | null | undefined;
11	
12	function ms(d: DateInput): number {
13	  if (!d) return 0;
14	  const t = new Date(d).getTime();
15	  return Number.isFinite(t) ? t : 0;
16	}
17	
18	/** Effective unlock instant (ms) or null when there's no schedule. */
19	export function unlockTime(folderPublishAt: DateInput, videoPublishAt: DateInput): number | null {
20	  const max = Math.max(ms(folderPublishAt), ms(videoPublishAt));
21	  return max > 0 ? max : null;
22	}
23	
24	/** Effective unlock time as ISO, or null when available now / unscheduled. */
25	export function unlockAtISO(folderPublishAt: DateInput, videoPublishAt: DateInput): string | null {
26	  const t = unlockTime(folderPublishAt, videoPublishAt);
27	  return t ? new Date(t).toISOString() : null;
28	}
29	
30	/** True when the content is scheduled for a future time (not yet watchable). */
31	export function isScheduledLocked(
32	  folderPublishAt: DateInput,
33	  videoPublishAt: DateInput,
34	  now: number = Date.now()
35	): boolean {
36	  const t = unlockTime(folderPublishAt, videoPublishAt);
37	  return t !== null && t > now;
38	}
39	
40	/** Parse a publishAt value from a request body into a Date | null for Prisma.
41	 *  Returns `undefined` when the field wasn't provided (leave unchanged). */
42	export function parsePublishAt(value: unknown): Date | null | undefined {
43	  if (value === null) return null; // explicit clear
44	  if (value === undefined) return undefined; // not provided
45	  if (typeof value !== "string" || !value.trim()) return null;
46	  const d = new Date(value);
47	  return Number.isFinite(d.getTime()) ? d : null;
48	}

