23	
24	  try {
25	    const purchase = await prisma.$transaction(async (tx) => {
26	      // Acquire transaction-scoped advisory lock to serialize purchases for the user
27	      await acquireAdvisoryLock(`purchase-video-${session.id}`, tx);
28	
29	      const video = await tx.video.findUnique({
30	        where: { id: videoId },
31	        include: { folder: { include: { course: { select: { id: true, teacherId: true, title: true } } } } },
