80	
81	      // 6. Create BalanceTransaction
82	      await tx.balanceTransaction.create({
83	        data: {
84	          userId: session.id,
85	          type: "debit_course",
86	          amount: -effectivePrice,
87	          note: `شراء كورس: ${course.title}`,
88	        },
89	      });
90	
91	      // 7. Process Teacher Referral Attribution
92	      await processTeacherAttribution({
93	        studentId: session.id,
94	        teacherIdOfContent: course.teacherId,
95	        amount: effectivePrice,
96	        purchaseType: "COURSE",
97	        courseId: course.id,
98	        promoCodeInput,
99	        tx,
100	      });
101	
102	      return {
103	        newBalance: +(currentBalance - effectivePrice).toFixed(2),
104	      };
105	    });
106	
107	    return NextResponse.json({
108	      success: true,
109	      courseId,
110	      courseTitle: course.title,
111	      charged: effectivePrice,
112	      newBalance: purchaseResult.newBalance,
113	      message: `تم شراء «${course.title}» بنجاح! خُصم ${effectivePrice} جنيه — رصيدك الآن ${purchaseResult.newBalance} جنيه.`,
114	    });
115	  } catch (err: any) {
116	    if (err.message === "ALREADY_ENROLLED") {
117	      return NextResponse.json({ error: "أنت مسجّل بالفعل في هذا الكورس" }, { status: 400 });
118	    }
119	    if (err.message === "USER_NOT_FOUND") {
120	      return NextResponse.json({ error: "المستخدم غير موجود" }, { status: 404 });
121	    }
122	    if (err.message === "INSUFFICIENT_FUNDS") {
123	      return NextResponse.json({ error: "رصيدك غير كافٍ لإتمام العملية" }, { status: 400 });
124	    }
125	    throw err;
126	  }
127	}

1	import { NextRequest, NextResponse } from "next/server";
2	import { prisma } from "@/lib/prisma";
3	import { getStudentSession } from "@/lib/auth";
4	import { acquireAdvisoryLock } from "@/lib/distributed-lock";
5	
6	export async function POST(req: NextRequest, { params }: { params: Promise<{ id: string }> }) {
7	  try {
8	    const { id } = await params;
9	    const session = await getStudentSession();
10	    if (!session) return NextResponse.json({ error: "غير مصرح" }, { status: 401 });
11	
12	    const plan = await prisma.plan.findUnique({
13	      where: { id },
14	    });
15	
16	    if (!plan || plan.status !== "published") {
17	      return NextResponse.json({ error: "الخطة غير متاحة" }, { status: 404 });
18	    }
19	
20	    let effectivePrice = plan.price;
21	    if (plan.discountPrice !== null && plan.discountExpiresAt && new Date(plan.discountExpiresAt) > new Date()) {
22	      effectivePrice = plan.discountPrice;
23	    }
24	
25	    const student = await prisma.user.findUnique({
26	      where: { id: session.id },
27	      select: { educationalStage: true, balance: true }
28	    });
29	
30	    if (student?.educationalStage && plan.educationalStage && student.educationalStage !== plan.educationalStage) {
31	      return NextResponse.json({ error: "هذه الخطة مخصصة لمرحلة دراسية مختلفة عن مرحلتك" }, { status: 400 });
32	    }
33	
34	    const alreadyEnrolled = await prisma.planEnrollment.findUnique({
35	      where: { planId_studentId: { planId: id, studentId: session.id } },
36	    });
37	    if (alreadyEnrolled) {
38	      return NextResponse.json({ error: "أنت مسجل بالفعل في هذه الخطة" }, { status: 400 });
39	    }
40	
41	    // Run transaction: deduct balance, create enrollment
42	    try {
43	      await prisma.$transaction(async (tx) => {
44	        // Acquire transaction-scoped advisory lock to serialize purchases for the user
45	        await acquireAdvisoryLock(`purchase-plan-${session.id}`, tx);
46	        if (effectivePrice > 0) {
47	          const student = await tx.user.findUnique({
48	            where: { id: session.id },
49	            select: { balance: true },
50	          });
51	
52	          if (!student || student.balance < effectivePrice) {
53	            throw new Error("INSUFFICIENT_FUNDS");
54	          }
55	
56	          await tx.user.update({
57	            where: { id: session.id },
58	            data: { balance: { decrement: effectivePrice } },
59	          });
60	
61	          await tx.balanceTransaction.create({
62	            data: {
63	              userId: session.id,
64	              type: "debit_purchase",
65	              amount: -effectivePrice,
66	              note: `شراء الخطة الدراسية: ${plan.title}`,
67	            },
68	          });
69	        }
70	
71	        const durationDays = plan.durationDays > 0 ? plan.durationDays : 365;
72	        await tx.planEnrollment.create({
73	          data: {
74	            planId: id,
75	            studentId: session.id,
76	            pricePaid: effectivePrice,
77	            expiresAt: new Date(Date.now() + durationDays * 24 * 60 * 60 * 1000),
78	          },
79	        });
80	      });
81	
82	      return NextResponse.json({ success: true, message: "تم شراء الخطة بنجاح" });
83	    } catch (e: any) {
84	      if (e.message === "INSUFFICIENT_FUNDS") {
85	        return NextResponse.json({ error: "الرصيد غير كافٍ لإتمام العملية" }, { status: 400 });
86	      }
87	      throw e;
88	    }
89	  } catch (error) {
90	    console.error("Plan purchase error:", error);
91	    return NextResponse.json({ error: "حدث خطأ أثناء الشراء" }, { status: 500 });
92	  }
93	}

1	import { prisma } from "./prisma";
