3	/**
4	 * Platform configuration — superadmin-editable constants that used to be
5	 * hardcoded. Values live in the PlatformConfig table; this module is the only
6	 * read/write path. A 60-second in-memory cache avoids a DB hit per request, and
7	 * setConfig() invalidates it immediately so edits take effect on the next call.
8	 */
9	
10	export type ConfigType = "number" | "string" | "boolean";
11	
12	interface ConfigDef {
13	  key: string;
14	  type: ConfigType;
15	  category: string;
16	  label: string;
17	  default: string;
18	}
19	
20	/** The full catalog. Defaults render when a row is absent; the panel lists these. */
21	export const CONFIG_DEFINITIONS: ConfigDef[] = [
22	  // ── Auth & Security ──
